import{at as e,it as t,n,vt as r}from"./chunks/framework.yntlMcNk.js";var i=JSON.parse(`{"title":"Editing the metamodel","description":"","frontmatter":{"title":"Editing the metamodel","covers":{"screens":[],"stories":["US-032","US-137","US-140"]}},"headers":[],"relativePath":"administration/metamodel-editing.md","filePath":"administration/metamodel-editing.md"}`),a={name:`administration/metamodel-editing.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="editing-the-metamodel" tabindex="-1">Editing the metamodel <a class="header-anchor" href="#editing-the-metamodel" aria-label="Permalink to “Editing the metamodel”">​</a></h1><p>Besides importing packages (see <a href="./metamodel-packages">Metamodel packages</a>), you maintain entity types and properties of your own organization. The form in the web portal follows; until then you edit the metamodel through the API. All operations require <code>metamodel:write</code> (role <code>metamodel-admin</code>) and are recorded in the audit trail with your name.</p><h2 id="entity-types" tabindex="-1">Entity types <a class="header-anchor" href="#entity-types" aria-label="Permalink to “Entity types”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;: &quot;SecurityZone&quot;, &quot;abbreviation&quot;: &quot;SZ&quot;, &quot;configId&quot;: &quot;00000000-0000-0000-0000-000000000001&quot;}&#39;</span></span></code></pre></div><ul><li>Entity types you create get the scope <code>organization</code> and can be used for entities at once.</li><li>Names are unique across all entity types, regardless of upper and lower case: <code>application component</code> is rejected with <code>409</code> (<code>name-taken</code>) while <em>Application Component</em> exists.</li><li>You change and delete only your own entity types. Built-in and imported ones are read-only (<code>409</code>, <code>read-only-metatype</code>); you can still add your own properties to them.</li><li>An entity type with entities – also deleted ones –, one used by a catalog or one that is the base type of another type cannot be deleted (<code>409</code>, <code>in-use</code>, with the number of entities in <code>count</code>).</li><li>Connection types follow in a later release; <code>isConnection: true</code> is rejected.</li></ul><h3 id="base-types" tabindex="-1">Base types <a class="header-anchor" href="#base-types" aria-label="Permalink to “Base types”">​</a></h3><p>With <code>baseMetatypeId</code>, an entity type inherits all properties of its base type and of the base type&#39;s own base types. <code>GET /metamodel/metatypes/{id}</code> lists the inherited properties with <code>inheritedFrom</code>. A property may appear only once in a chain; base types cannot form a cycle. Packages can name a base type of the same package or a built-in one.</p><p>If you change the base type of your own entity type, it loses the properties of the old base type – with their values, see below – and gains those of the new one.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/property-definitions&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;: &quot;Trust Level&quot;, &quot;dataType&quot;: &quot;enum&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/property-definitions/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROPERTY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/enum-values&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;value&quot;: &quot;high&quot;}&#39;</span></span></code></pre></div><ul><li>Data types: <code>string</code>, <code>text</code>, <code>integer</code>, <code>boolean</code>, <code>date</code>, <code>url</code> and <code>enum</code>. Reference properties follow with the connection types.</li><li>OEA derives the storage name <code>sqlColumnName</code> from the name, for example <code>trust_level</code>. It is used in reports and never changes, even if you rename the property.</li><li>You cannot change the data type once entities have values for the property, also in their history.</li><li>A property that is still assigned to an entity type cannot be deleted. A property that appears in the history of entities is retired instead: it disappears from the lists, and its name stays taken.</li><li>Property categories (<code>/metamodel/property-categories</code>) group properties; a category with properties cannot be deleted.</li></ul><h2 id="assigning-properties-to-entity-types" tabindex="-1">Assigning properties to entity types <a class="header-anchor" href="#assigning-properties-to-entity-types" aria-label="Permalink to “Assigning properties to entity types”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TYPE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/property-mappings&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;propertyDefId&quot;: &quot;&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROPERTY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&#39;&quot;, &quot;necessity&quot;: &quot;mandatory&quot;}&#39;</span></span></code></pre></div><ul><li>You assign your own properties to any entity type, also to imported and built-in ones. The properties of a package stay unchanged.</li><li>The necessity is <code>mandatory</code>, <code>warning</code> or <code>optional</code>; <code>validFrom</code> defaults to today.</li></ul><h3 id="a-new-mandatory-property" tabindex="-1">A new mandatory property <a class="header-anchor" href="#a-new-mandatory-property" aria-label="Permalink to “A new mandatory property”">​</a></h3><p>Assigning a mandatory property always succeeds, even if entities exist. OEA marks every existing entity of the type and its subtypes without a value; the response states the number in <code>markedEntityCount</code>. A marked entity keeps working until someone changes it: saving it without the value is rejected with <code>MANDATORY_MISSING</code>. Setting the value removes the mark.</p><p>Mandatory properties are checked only where the writer can change them. Properties with restricted visibility cannot be written yet, so they are never reported as missing.</p><h3 id="changing-the-necessity-by-effective-date" tabindex="-1">Changing the necessity by effective date <a class="header-anchor" href="#changing-the-necessity-by-effective-date" aria-label="Permalink to “Changing the necessity by effective date”">​</a></h3><p>A metamodel evolves: a property that is optional today can become mandatory from a certain date. Assign the property again with the new necessity and the date from which it applies:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TYPE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/property-mappings&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;propertyDefId&quot;: &quot;&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROPERTY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&#39;&quot;, &quot;necessity&quot;: &quot;mandatory&quot;, &quot;validFrom&quot;: &quot;2027-01-01&quot;}&#39;</span></span></code></pre></div><ul><li>The earlier entries stay; the entry with the latest date not after today applies. A second entry with the same date is rejected with <code>409</code> (<code>conflict</code>).</li><li>A date in the past applies at once. On a future date, OEA marks the entities without a value when the date is reached – at the latest about ten minutes after midnight (UTC) – and writes the audit event <code>metamodel.mapping-effective</code>. If a property is no longer mandatory, its marks disappear.</li><li>This also works for the properties of a package, for example to make <em>Status</em> mandatory. Your entry has the scope <code>organization</code>; the package stays unchanged. If the package itself brings an entry on the same date, yours wins.</li><li>Entries are made on the entity type that holds the property, not on its subtypes.</li><li><code>GET /metamodel/metatypes/{id}/property-mappings</code> shows the entries in effect today; with <code>?includeHistory=true</code> you get all entries with their <code>state</code> (<code>past</code>, <code>active</code>, <code>future</code>).</li><li>To correct an entry, remove it and add a new one. Removing one of several entries of a property deletes no values.</li></ul><h3 id="removing-a-property" tabindex="-1">Removing a property <a class="header-anchor" href="#removing-a-property" aria-label="Permalink to “Removing a property”">​</a></h3><p>Removing an assignment of your own property – or one of your entries – is always possible:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TYPE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/property-mappings/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MAPPING</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Values are deleted</p><p>If the entity type then no longer has the property and entities of the type or its subtypes have values for it, these values are deleted. Every affected entity gets a new version; the removed value remains visible in its history. The audit event <code>metamodel.mapping-deleted</code> states the number of affected entities. Deleting a value of an enum property works the same way for the entities that hold this value.</p></div><h2 id="translating-labels" tabindex="-1">Translating labels <a class="header-anchor" href="#translating-labels" aria-label="Permalink to “Translating labels”">​</a></h2><p>Users see the names of entity types, categories and properties and the values of enum properties in the language of their user interface (see <a href="./../usage/login#your-profile">Your profile</a>). You maintain the translations per language – <code>de</code>, <code>en</code>, <code>fr</code> or <code>it</code> – through the API until the form in the web portal follows:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/labels/de&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # every element with its name, package label and your label</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/labels/de&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;labels&quot;: {&quot;metatype.&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TYPE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&#39;.name&quot;: &quot;Anwendungskomponente&quot;, &quot;enum-value.&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$VALUE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&#39;.label&quot;: &quot;&quot;}}&#39;</span></span></code></pre></div><ul><li>A label key names the element by its identifier: <code>metatype.{id}.name</code>, <code>property-category.{id}.name</code>, <code>property-def.{id}.label</code> or <code>enum-value.{id}.label</code>. Keys you do not name stay unchanged; an empty text removes your label. Texts have at most 200 characters.</li><li>You can translate every element, also those of a package. Your label wins over the label of the package; without either, users see the name in your corporate language.</li><li>An unknown key rejects the whole change with <code>422</code> (<code>validation-failed</code>) naming the keys. Every change writes the audit event <code>metamodel.labels-changed</code>.</li><li>Open web portals pick up a change within five minutes, without a reload.</li></ul><h2 id="organization-properties-at-a-package-re-import" tabindex="-1">Organization properties at a package re-import <a class="header-anchor" href="#organization-properties-at-a-package-re-import" aria-label="Permalink to “Organization properties at a package re-import”">​</a></h2><p>When a package is imported again, it replaces its own properties of its entity types. Whether your own properties and entries on these types stay depends on the way you work, so you configure it:</p><ul><li><strong>Globally</strong> with <code>PUT /metamodel/settings/reimport-policy</code> and <code>{&quot;organizationMappings&quot;: &quot;keep&quot;}</code> (default) or <code>&quot;remove&quot;</code>.</li><li><strong>Per entity type</strong> with <code>PUT /metamodel/metatypes/{id}/reimport-policy</code> and <code>inherit</code> (default), <code>keep</code> or <code>remove</code>. <code>inherit</code> takes the setting of the base type; at the top of the chain the global setting applies. <code>GET /metamodel/metatypes/{id}</code> shows the own value in <code>reimportPolicy</code> and the applying one in <code>effectiveReimportPolicy</code>.</li></ul><p>Removing at a re-import deletes the values as described above.</p>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};